import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../core/services/api.service';

@Component({
  selector: 'app-admin-inquiries',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="page-header"><div class="container"><h2>Quản lý Yêu cầu tư vấn</h2></div></div>
    <section class="section">
      <div class="container">
        <div style="margin-bottom:1rem;">
          <select class="form-control" style="max-width:200px;" [(ngModel)]="filterStatus" (change)="load()">
            <option value="">Tất cả</option>
            <option value="pending">Chờ xử lý</option>
            <option value="replied">Đã trả lời</option>
            <option value="closed">Đã đóng</option>
          </select>
        </div>
        <div class="loading-spinner" *ngIf="loading"><div class="spinner"></div></div>
        <table class="data-table" *ngIf="!loading">
          <thead><tr><th>Ngày</th><th>Tên</th><th>Email</th><th>Tiêu đề</th><th>Loại</th><th>Trạng thái</th><th>Hành động</th></tr></thead>
          <tbody>
            <tr *ngFor="let i of inquiries">
              <td>{{ i.createdAt | date:'dd/MM/yyyy' }}</td>
              <td>{{ i.name }}</td>
              <td>{{ i.email }}</td>
              <td>{{ i.subject }}</td>
              <td><span class="badge badge-primary">{{ i.type }}</span></td>
              <td>
                <select class="form-control" style="font-size:0.8125rem;padding:0.25rem 0.5rem;" [(ngModel)]="i.status" (change)="updateStatus(i)">
                  <option value="pending">Chờ</option>
                  <option value="replied">Đã trả lời</option>
                  <option value="closed">Đã đóng</option>
                </select>
              </td>
              <td><button class="btn btn-sm btn-danger" (click)="delete(i.id)">Xóa</button></td>
            </tr>
          </tbody>
        </table>
      </div>
    </section>
  `
})
export class AdminInquiriesComponent implements OnInit {
  inquiries: any[] = [];
  loading = true;
  filterStatus = '';
  constructor(private api: ApiService) {}
  ngOnInit() { this.load(); }
  load() {
    this.loading = true;
    const params: any = {};
    if (this.filterStatus) params.status = this.filterStatus;
    this.api.getInquiries(params).subscribe((data: any) => { this.inquiries = data.data; this.loading = false; }, () => { this.loading = false; });
  }
  updateStatus(inq: any) {
    this.api.updateInquiry(inq.id, { status: inq.status }).subscribe();
  }
  delete(id: string) {
    if (confirm('Xác nhận xóa?')) this.api.deleteInquiry(id).subscribe(() => this.load());
  }
}
